{
    /**
     * Возвращает DOM-контейнер горизонтального скролла табов.
     *
     * @returns {HTMLElement | null} Контейнер скролла или null.
     */
    const getTabsScrollContainer = () => {
        return tabsRootRef.value?.querySelector('.v-x-scroll') as HTMLElement | null;
    };

    /**
     * Прокручивает панель вкладок влево на фиксированный шаг.
     */
    const scrollLeft = () => {
        const container = getTabsScrollContainer();
        if (container) {
            container.scrollBy({ left: -TABS_SCROLL_STEP, behavior: 'smooth' });
        }
    };

    /**
     * Прокручивает панель вкладок вправо на фиксированный шаг.
     */
    const scrollRight = () => {
        const container = getTabsScrollContainer();
        if (container) {
            container.scrollBy({ left: TABS_SCROLL_STEP, behavior: 'smooth' });
        }
    };

    return {
        scrollLeft,
        scrollRight,
    };
}

{
    /** Ключ строки, на которой фокусируется таблица */
    const focusedRowKey = ref<RowKey | null>(null);
    /** Ключи строк, которые раскрыты в режиме master-detail */
    const expandedRowKeys = ref<RowKey[]>([]);
    /** Ключи строк, выделенных в таблице */
    const checkedRowKeys = ref<RowKey[]>([]);
    /** Ссылка на данные таблицы */
    const data = ref<DataTableRowData[]>([]);
    /** Настройки тулбара таблицы */
    const tableSettings = reactive<TableToolbarSettings>({ ...DEFAULT_TABLE_TOOLBAR_SETTINGS });
    /** Ключ для принудительного пересоздания `NDataTable` при сбросе настроек */
    const tableResetKey = ref(Math.random());
    const { tableApi } = useGlobalSettings();

    /** Возвращает ключ строки по `keyExpr` */
    const getRowKey = (row: DataTableRowData) => row[keyExpr];
    /** Проверяет, является ли строка фокусированной */
    const isFocusedRow = (row: DataTableRowData) => row[keyExpr] === focusedRowKey.value;
    /** Проверяет, является ли строка выделенной */
    const isCheckedRow = (row: DataTableRowData) => checkedRowKeys.value.includes(row[keyExpr]);

    /** Идентификатор таймера отложенного автосохранения */
    let autoSaveTimeoutId: ReturnType<typeof setTimeout> | null = null;

    /** Обновляет данные, сбрасывает выделение и восстанавливает фокус строки */
    const resetState = (incomingData: DataTableRowData[], savedFocusedRowKey?: RowKey | null) => {
        data.value = incomingData;
        const hasSavedFocus =
            savedFocusedRowKey !== null && incomingData.some(row => row[keyExpr] === savedFocusedRowKey);
        focusedRowKey.value = hasSavedFocus ? savedFocusedRowKey : (incomingData.at(0)?.[keyExpr] ?? null);
        checkedRowKeys.value.length = 0;
    };

    /** Актуализирует фокус, выделение и раскрытые строки после изменения данных */
    const syncState = () => {
        focusedRowKey.value = data.value.find(row => row[keyExpr] === focusedRowKey.value)?.[keyExpr] ?? null;
        checkedRowKeys.value = data.value
            .filter(row => checkedRowKeys.value.includes(row[keyExpr]))
            .map(row => row[keyExpr]);
        expandedRowKeys.value = data.value
            .filter(row => expandedRowKeys.value.includes(row[keyExpr]))
            .map(row => row[keyExpr]);
    };

    /** Текущий снимок настроек таблицы для сохранения */
    const tableSettingsSnapshot = computed<TableSettings>(() => ({
        autoSaveMode: tableSettings.autoSaveMode,
        groupPanelVisible: tableSettings.groupPanelVisible,
        focusedRow: focusedRowKey.value,
        columns: getColumnsSettings(),
    }));

    /** Проверка существаования `viewId` таблицы */
    const resolveViewId = (): string | null => {
        const viewId = tableProps.viewId;
        if (!viewId) {
            console.error('viewId не указан, настройки таблицы не могут быть сохранены или загружены');
            return null;
        }
        return viewId;
    };
    /** Сохраняет пользовательские настройки таблицы на сервере */
    const setUserDataChanges = async (changes: TableSettings) => {
        const viewId = resolveViewId();
        if (!viewId) return false;

        try {
            const response = await tableApi.userChanges(tableApi.userSettingsApi.set, {
                settings: changes,
                viewId,
            });
            return !!response?.result;
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            console.error(`Ошибка при сохранении настроек: ${errorMessage}`);
            return false;
        }
    };

    /** Загружает сохранённые пользовательские настройки таблицы */
    const getUserDataChanges = async (): Promise<TableSettings | null> => {
        const viewId = resolveViewId();
        if (!viewId) return null;

        try {
            const response = await tableApi.userChanges(tableApi.userSettingsApi.get, {
                viewId,
            });
            if (response?.result) {
                return response.settings;
            }
            return null;
        } catch (error) {
            const errorMessage = error instanceof Error ? error.message : String(error);
            console.error(`Ошибка при загрузке настроек: ${errorMessage}`);
            return null;
        }
    };

    /** Отменяет отложенное автосохранение */
    const cancelScheduledAutoSave = () => {
        if (autoSaveTimeoutId !== null) {
            clearTimeout(autoSaveTimeoutId);
            autoSaveTimeoutId = null;
        }
    };

    /** Планирует автосохранение настроек таблицы */
    const triggerAutoSave = () => {
        if (!tableSettings.autoSaveMode) return;

        cancelScheduledAutoSave();
        autoSaveTimeoutId = setTimeout(async () => {
            autoSaveTimeoutId = null;
            await setUserDataChanges(tableSettingsSnapshot.value);
        }, AUTO_SAVE_DEBOUNCE_MS);
    };

    /** Устанавливает фокус на строку */
    const setFocusedRow = (row: DataTableRowData) => {
        if (focusedRowKey.value === row[keyExpr]) return;

        focusedRowKey.value = row[keyExpr];
        triggerAutoSave();
    };

    /** Обрабатывает изменение ширины колонки при ресайзе */
    const handleColumnResize = (_: number, newWidth: number, column: DataTableBaseColumn) => {
        updateColumnWidth?.(String(column.key), newWidth);
    };

    /** Сбрасывает настройки тулбара к значениям по умолчанию */
    const resetTableToolbarSettings = () => {
        tableSettings.autoSaveMode = DEFAULT_TABLE_TOOLBAR_SETTINGS.autoSaveMode;
        tableSettings.groupPanelVisible = DEFAULT_TABLE_TOOLBAR_SETTINGS.groupPanelVisible;
    };

    /** Применяет загруженные настройки (если их нет, берем дефолтные) и возвращает сохранённый ключ фокусной строки */
    const applyTableSettings = (settings: TableSettings): RowKey | null => {
        tableSettings.autoSaveMode = settings.autoSaveMode ?? DEFAULT_TABLE_TOOLBAR_SETTINGS.autoSaveMode;
        tableSettings.groupPanelVisible =
            settings.groupPanelVisible ?? DEFAULT_TABLE_TOOLBAR_SETTINGS.groupPanelVisible;
        applyColumnsSettings(settings.columns);

        return settings.focusedRow;
    };

    /** Обработчики действий выпадающего меню настроек тулбара по ключу */
    const settingsChangeHandlers: Record<SettingsDropdownKey, () => void | Promise<void>> = {
        'save-settings': async () => {
            await setUserDataChanges(tableSettingsSnapshot.value);
        },
        'reset-settings': () => {
            resetTableToolbarSettings();
            rebuildColumns();
            tableResetKey.value = Math.random();
            onResetState();
            triggerAutoSave();
        },
        'auto-save': async () => {
            cancelScheduledAutoSave();
            tableSettings.autoSaveMode = !tableSettings.autoSaveMode;
            await setUserDataChanges(tableSettingsSnapshot.value);
        },
        'show-grouping': () => {
            tableSettings.groupPanelVisible = !tableSettings.groupPanelVisible;
            triggerAutoSave();
        },
    };

    /** Обрабатывает действие из выпадающего меню настроек тулбара */
    const handleSettingsChange = async (action: SettingsDropdownKey) => {
        await settingsChangeHandlers[action]();
    };

    /** Отслеживаем изменения для автоматического сохранения пользовательских настроек */
    watch(tableSettingsSnapshot, () => triggerAutoSave(), { deep: true });

    /** Отменяет отложенное автосохранение при размонтировании таблицы, чтобы не отправлять устаревший снимок настроек */
    onScopeDispose(() => {
        cancelScheduledAutoSave();
    });

    return {
        focusedRowKey,
        expandedRowKeys,
        checkedRowKeys,
        tableSettings,
        tableResetKey,
        getRowKey,
        resetState,
        syncState,
        isFocusedRow,
        isCheckedRow,
        setFocusedRow,
        handleSettingsChange,
        handleColumnResize,
        tableSettingsSnapshot,
        getUserDataChanges,
        applyTableSettings,
    };
}

{
    const parentRowKey = inject('parentRowKey');
    const cacheKey = parentRowKey ? `${tableProps.viewId}:${parentRowKey}` : tableProps.viewId;
    const { state: store, fromCache } = useCache(cacheKey);

    const {
        isDirty,
        rowChangesByRowKey,
        newRows,
        resetChanges,
        isModified,
        trackInsert,
        trackUpdate,
        trackDelete,
        getUpdatedRowKeys,
        getInsertedRowKeys,
    } = useChangesTracker(store.rowChangesByRowKey, store.newRows);

    const {
        data,
        loading,
        getData,
        getDataRowIndexByKey,
        setData: setLocalData,
        saveModifiedData,
        updateRowField,
        insertNewRow,
        createCopiedRow,
        deleteRows,
        getVirtualScrollTools,
        getValidationErrorMessage,
        applyChangesToData,
    } = useDataStore(tableProps, keyExpr, rowChangesByRowKey, newRows, store.data);

    const dialog = useDialog();

    /**
     * Первая загрузка при монтировании.
     */
    const initData = async () => {
        if (fromCache) return true;
        return loadData();
    };

    /**
     * Загружает данные с сервера. Всегда идёт в сеть (refresh / после save).
     */
    const loadData = async () => {
        if (isDirty.value) {
            const choice = await dialog.show({
                content: 'Есть несохраненные изменения. Сохранить изменения?',
                positiveText: 'Да',
                negativeText: 'Нет',
                neutralText: 'Отмена',
            });
            if (choice === 'positive') {
                const success = await saveData();
                return success;
            }
            if (choice === 'negative') {
                const success = await getData();
                if (success) resetChanges();
                return success;
            }
            if (choice === 'neutral') return false;
        }
        const success = await getData();
        return success;
    };

    /**
     * Сохраняет данные на сервер и сбрасывает состояние изменений
     */
    const saveData = async () => {
        const updatedRowKeys = getUpdatedRowKeys();
        const insertedRowKeys = getInsertedRowKeys();
        const success = await saveModifiedData(updatedRowKeys, insertedRowKeys);
        if (success) {
            resetChanges();
            await loadData();
        }
        return success;
    };

    /**
     * Создает новую строку и отслеживает ее
     */
    const createRow = (focusedRowKey: RowKey | null) => {
        const [newRowKey, newRowData] = insertNewRow(focusedRowKey);
        trackInsert(newRowKey, newRowData);
    };

    /**
     * Удаляет строки из данных и отслеживает удаленные строки
     *
     * @param keys - Массив ключей строк
     */
    const removeRows = async (keys: RowKey[]) => {
        const choice = await dialog.show({
            content: 'Строки будут безвозвратно удалены. Продолжить?',
            positiveText: 'Да',
            negativeText: 'Нет',
        });
        if (choice === 'positive') {
            const successDelete = await deleteRows(keys);
            if (successDelete) {
                trackDelete(keys);
                const successLoad = await getData();
                if (successLoad) {
                    applyChangesToData(false);
                }
                return successLoad;
            }
            return successDelete;
        }
        return false;
    };

    /**
     * Изменяет значение поля в строке и отслеживает изменение
     *
     * @param key - Значение ключа строки
     * @param dataField - Название поля для изменения
     * @param newValue - Новое значение
     */
    const updateRow = (key: RowKey, dataField: string, newValue: DataFieldValue) => {
        const oldValue = updateRowField(key, dataField, newValue);
        trackUpdate(key, dataField, oldValue, newValue);
    };

    /**
     * Копирует строку и отслеживает копию
     *
     * @param key - Значение ключа строки
     */
    const copyRow = (key: RowKey | null) => {
        if (key === null) return;
        const [newRowKey, newRowData] = createCopiedRow(key);
        if (!newRowKey) return false;
        trackInsert(newRowKey, newRowData);
        return true;
    };

    /**
     * Устанавливает данные таблицы и сбрасывает состояние изменений
     */
    const setData = (newData: DataTableRowData[]) => {
        setLocalData(newData);
        resetChanges();
    };

    return {
        data,
        loading,
        isDirty,
        updateRow,
        getDataRowIndexByKey,
        isModified,
        getValidationErrorMessage,
        initData,
        loadData,
        saveData,
        setData,
        createRow,
        copyRow,
        removeRows,
        getVirtualScrollTools,
    };
}

{
    /** Массив сконфигурированных колонок */
    const allColumns = reactive<Column[]>([]);
    const visibleColumns = computed<Column[]>((): Column[] => (allColumns as Column[]).filter(isVisibleColumn));
    const columnsChooser = reactive<ColumnChooser>({
        options: [],
        value: [],
    });
    const isTableEditable = ref(false);
    /** Немедленное значение поля ввода (для отображения в тулбаре) */
    const searchValue = ref('');
    /** Отложенный (debounce 500мс) и уже нормализованный термин: питает фильтрацию и подсветку */
    const searchTerm = ref('');
    let searchDebounceTimer: ReturnType<typeof setTimeout> | undefined;

    const {
        filterState,
        setFilterInput,
        setDateFilterState,
        updateFilterState,
        getNaiveFilterConfigFunction,
        applyFilterSelection,
    } = useFilterState();

    const setupColumnChooser = () => {
        const baseColumns: BaseColumn[] = (allColumns as Column[]).filter(isBaseColumn);
        const choosableColumns = baseColumns.filter(column => column.showInColumnChooser !== false);

        columnsChooser.options = choosableColumns.map(column => ({
            value: column.dataField,
            label: column.caption ?? '',
        }));

        columnsChooser.value = choosableColumns
            .filter(column => column.visible === true)
            .map(column => column.dataField);
    };

    const setColumnsVisibility = (incomingVisibleColumns: string[]) => {
        if (incomingVisibleColumns.length === 0) return;
        const visibleColumns = [];
        for (const column of allColumns as Column[]) {
            if (!isBaseColumn(column)) continue;
            column.visible = isAlwaysVisibleColumn(column) || incomingVisibleColumns.includes(column.dataField);
            if (column.showInColumnChooser !== false && column.visible) visibleColumns.push(column.dataField);
        }
        columnsChooser.value.length = 0;
        columnsChooser.value.push(...visibleColumns);
    };

    const reorderColumns = (fromDataField: string, toDataField: string) => {
        const columns = allColumns as Column[];
        const fromIndex = columns.findIndex(column => isBaseColumn(column) && column.dataField === fromDataField);
        const toIndex = columns.findIndex(column => isBaseColumn(column) && column.dataField === toDataField);
        if (fromIndex === -1 || toIndex === -1) return;

        const [movedColumn] = columns.splice(fromIndex, 1);
        if (!movedColumn) return;
        columns.splice(toIndex, 0, movedColumn);
    };

    const getColumnsSettings = (): TableColumnSettings[] => {
        let visibleIndex = 0;
        const flattenedColumns = flattenBaseColumns(allColumns as Column[]);

        return flattenedColumns.map(column => {
            visibleIndex += 1;

            return {
                visibleIndex,
                dataField: column.dataField,
                width: Number(column.width),
                visible: !!column.visible,
            };
        });
    };

    const updateColumnWidth = (dataField: string, width: number) => {
        const column = findBaseColumnByDataField(allColumns as Column[], dataField);
        if (column) column.width = width;
    };

    const setSearchValue = (value: string) => {
        searchValue.value = value;
        clearTimeout(searchDebounceTimer);
        searchDebounceTimer = setTimeout(() => {
            searchTerm.value = value.trim().toLowerCase();
        }, SEARCH_DEBOUNCE_MS);
    };

    /** Проверяет, содержит ли строка искомую подстроку хотя бы в одном из видимых полей. `term` уже нормализован */
    const matchesSearch = (row: DataTableRowData, searchableColumns: BaseColumn[], term: string): boolean => {
