        // Удаляем запись из updatedRows, если больше нет изменений
        if (Object.keys(rowChanges).length === 0) rowChangesByRowKey.delete(key);
    };

    const trackDelete = (keys: RowKey[]) => {
        for (const key of keys) {
            newRows.delete(key);
