    const has = (key: Key) => cache.has(key);

    /** Текущее количество записей в кэше */
    const size = () => cache.size;

    /**
     * Возвращает значение по ключу и помечает запись как недавно использованную.
     * Если записи нет, возвращает `undefined`.
     *
     * @param key - Ключ записи
     */
    const get = (key: Key) => {
        const data = cache.get(key);
        if (data === undefined) return;

        cache.delete(key);
        cache.set(key, data);
        return data;
    };

    /**
     * Добавляет или обновляет запись. При переполнении удаляет наименее используемую.
     *
     * @param key - Ключ записи
     * @param data - Значение для сохранения
     */
    const set = (key: Key, data: Value) => {
        if (cache.has(key)) {
            cache.delete(key);
        } else if (cache.size >= maxSize) {
            let evicted = false;
            for (const [k, value] of cache) {
                if (isEvictable(value)) {
                    cache.delete(k);
                    evicted = true;
                    break;
                }
            }
            if (!evicted) {
                const oldestKey = cache.keys().next().value;
                if (oldestKey !== undefined) cache.delete(oldestKey);
            }
        }
        cache.set(key, data);
    };

    /* Удаляет запись по ключу */
    const remove = (key: Key) => cache.delete(key);

    /** Очищает весь кэш */
    const clear = () => {
        cache.clear();
    };

    return {
        size,
        has,
        get,
        set,
        remove,
        clear,
